+    public boolean canManage(GroupModel group) {
+        if (root.hasOneAdminRole(AdminRoles.MANAGE_USERS)) {
+            return true;
+        }
+
+        return hasPermission(group.getId(), AdminPermissionsSchema.MANAGE);
+    }
+
+    @Override
